/*
Regime Classifier -- Procedure Initialization.

Everything is computed here, once, over the whole main dependency (Candles), and stored in
variable.out[index]; the Procedure Loop only picks the row for the current record.

Multi-time-frame: an SA Multi-Time-Frame-Market process only receives its dependencies at the
time frame it is running (MultiTimeFrameMarket.js getFile), so the 4h / 12h / 24h bars are
aggregated here from the base candles (UTC-aligned buckets, exactly how Candles-Volumes builds
its market files). Every indicator is a pure step function over bars, so a higher-time-frame
value can be taken from the still FORMING bar (default: the partial bar up to and including the
current candle -- causal, and the closest to the reference) or from the last CLOSED bar (what
chart.atXXhs shows a strategy). 'lookahead' replays the old h4x behaviour
(completed bar matched by begin time -- it uses future data) and exists only to validate the
port against the h4x reference; never use it for trading.

Baseline label = port of h4x backtester/feature_builder_fast.py::_add_regime_detection (V3):
RSI(14) + Waddah Attar trend + DMI ADX(14) on 1h/4h/12h/24h. Indicator math replicates the
Zeus RSI, Pluvtech Waddah and Zeus DMI data building procedures bit for bit.
On top: regime ages, a hysteresis ("stable") coarse regime, per-time-frame heat and a
multi-timescale heat index, and Waddah-style volume force / pressure / climax / drying-up.
Design and formulas: docs/regime-strategies-plan.md.
*/
variable.out = (function buildRegimeClassifier() {
    const HOUR = 3600000
    const DAY = 86400000

    /* ---------------------------------------------------------------- parameters */
    const P = {
        htfMode: 'forming',     // 'forming' | 'closed' | 'lookahead' (validation only -- uses future data)
        rsiBull: 50,
        adxTrending: 25,
        /* 'adx' = mean ADX(14) of 1h/4h/12h/24h, as the h4x code documents. 'plusDI' replays
        the h4x reference exactly: its loader read DMI columns by position, so its "adx" was +DI. */
        strengthSource: 'adx',
        /* Waddah Attar settings of the DCHF workspace's Pluvtech mine, which the h4x reference
        was computed from (the Pluvtech plugin defaults are 150 / 20 / 40 / 20 / 2 / 100). */
        wSensitivity: 140, wFast: 16, wSlow: 32, wChannel: 24, wStdMult: 2.0, wDeadLen: 72,
        stableHours: 24,        // hysteresis for coarse_stable
        heatHot: 40,            // per-time-frame hot / cold threshold for heat_agreement
        heatStrong: 60,         // OVERHEATED / BOTTOMED threshold for heat_state
        heatMild: 30,           // HOT / COLD threshold for heat_state
        volFast: 10, volSlow: 100, volPressureLen: 20,
        climaxSpike: 2.5, climaxHeat: 40, dryForce: 0.7,
        debug: false            // true: expose the per-time-frame indicator series (offline checks)
    }
    if (typeof parameters === 'object' && parameters !== null) {
        for (const k of Object.keys(P)) {
            if (parameters[k] !== undefined) { P[k] = (typeof P[k] === 'number') ? Number(parameters[k]) : parameters[k] }
        }
    }

    const candles = mainDependency.records
    const baseTF = (typeof system === 'object' && system.timeFrame) ? system.timeFrame : HOUR
    const volumeByBegin = new Map()
    if (products.volumes !== undefined) {
        for (const v of products.volumes) { volumeByBegin.set(v.begin, (Number(v.buy) || 0) + (Number(v.sell) || 0)) }
    }

    const TFS = [
        { key: '01h', ms: HOUR }, { key: '04h', ms: 4 * HOUR },
        { key: '12h', ms: 12 * HOUR }, { key: '24h', ms: 24 * HOUR }
    ]

    /* ---------------------------------------------------------------- indicator steps
    Each step(state, bar) returns { state, out } and never mutates its inputs. */
    function round2(x) { return Number(Number(x).toFixed(2)) }

    function rsiStep(s, bar) {                           // Zeus "RSI + StochRSI"
        const prevClose = s.prevClose === undefined ? bar.close : s.prevClose
        const up = round2(Math.max(bar.close - prevClose, 0))
        const down = round2(Math.max(prevClose - bar.close, 0))
        const upRMA = up / 14 + (1 - 1 / 14) * s.upRMA
        const downRMA = down / 14 + (1 - 1 / 14) * s.downRMA
        const rs = downRMA > 0 ? upRMA / downRMA : 0
        const rsi = round2(100 - 100 / (1 + rs))
        const lastRSI = s.lastRSI.concat([rsi]).slice(-14)
        let stoch = 0
        if (lastRSI.length >= 14) {
            const hi = Math.max(...lastRSI), lo = Math.min(...lastRSI)
            if (hi - lo > 0) { stoch = round2(100 * (rsi - lo) / (hi - lo)) }
        }
        const lastStoch = s.lastStoch.concat([stoch]).slice(-3)
        const k = lastStoch.length < 3 ? 0 : round2((lastStoch[0] + lastStoch[1] + lastStoch[2]) / 3)
        const lastK = s.lastK.concat([k]).slice(-3)
        const d = lastK.length < 3 ? 0 : round2((lastK[0] + lastK[1] + lastK[2]) / 3)
        return {
            state: { prevClose: bar.close, upRMA, downRMA, lastRSI, lastStoch, lastK },
            out: { rsi, stoch, k, d }
        }
    }
    function rsiInit() { return { prevClose: undefined, upRMA: 0, downRMA: 0, lastRSI: [], lastStoch: [], lastK: [] } }

    function waddahStep(s, bar) {                         // Pluvtech "Waddah Attar" (+ Bollinger %B)
        const closes = s.closes.concat([bar.close]).slice(-60)
        const n = s.count + 1
        if (n < P.wChannel || n < P.wFast || n < P.wSlow) {
            return { state: Object.assign({}, s, { closes, count: n }), out: { up: 0, down: 0, explosion: 0, deadZone: 0, pctB: 0.5 } }
        }
        const ema = (src, len, prev) => src * (2 / (len + 1)) + prev * (1 - 2 / (len + 1))
        const prevClose = closes[closes.length - 2]
        const macdNow = ema(bar.close, P.wFast, s.fPrev) - ema(bar.close, P.wSlow, s.sPrev)
        const macdPrev = ema(prevClose, P.wFast, s.fPrevPrev) - ema(prevClose, P.wSlow, s.sPrevPrev)
        const t1 = (macdNow - macdPrev) * P.wSensitivity
        const win = closes.slice(-P.wChannel)
        const mean = win.reduce((a, b) => a + b, 0) / win.length
        const sd = Math.sqrt(win.reduce((q, x) => q + (x - mean) * (x - mean), 0) / (win.length - 1))
        const upper = mean + P.wStdMult * sd, lower = mean - P.wStdMult * sd
        const explosion = upper - lower
        const tr = Math.max(bar.max - bar.min, Math.abs(bar.max - prevClose), Math.abs(bar.min - prevClose))
        const deadSum = s.deadSum === 0 ? tr : tr / P.wDeadLen + (1 - 1 / P.wDeadLen) * s.deadSum
        return {
            state: {
                closes, count: n, deadSum,
                fPrevPrev: s.fPrev, sPrevPrev: s.sPrev,
                fPrev: ema(bar.close, P.wFast, s.fPrev), sPrev: ema(bar.close, P.wSlow, s.sPrev)
            },
            out: {
                up: t1 >= 0 ? t1 : 0, down: t1 < 0 ? -t1 : 0, explosion, deadZone: deadSum * 3.7,
                pctB: explosion > 0 ? (bar.close - lower) / explosion : 0.5
            }
        }
    }
    function waddahInit() { return { closes: [], count: 0, deadSum: 0, fPrev: 0, sPrev: 0, fPrevPrev: 0, sPrevPrev: 0 } }

    function dmiStep(s, bar) {                            // Zeus "DMI"
        let up = 0, down = 0, prevClose = bar.close
        if (s.prev !== undefined) {
            up = bar.max - s.prev.max
            down = s.prev.min - bar.min
            prevClose = s.prev.close
        }
        const plusDM = (up > down && up > 0) ? up : 0
        const minusDM = (down > up && down > 0) ? down : 0
        const hl = bar.max - bar.min
        const tr = (prevClose === 0 || isNaN(prevClose)) ? hl : Math.max(hl, Math.abs(bar.max - prevClose), Math.abs(bar.min - prevClose))
        const a = 1 / 14
        const trur = a * tr + (1 - a) * s.trur
        const k = 100 / trur
        const bp = a * plusDM + (1 - a) * s.bp
        const bm = a * minusDM + (1 - a) * s.bm
        let plusDI = bp * k; if (isNaN(plusDI)) { plusDI = 0 }
        let minusDI = bm * k; if (isNaN(minusDI)) { minusDI = 0 }
        let sum = plusDI + minusDI; if (sum == 0) { sum = 1 }
        const ba = a * (Math.abs(plusDI - minusDI) / sum) + (1 - a) * s.ba
        return {
            state: { prev: { max: bar.max, min: bar.min, close: bar.close }, trur, bp, bm, ba },
            out: { adx: 100 * ba, plusDI, minusDI }
        }
    }
    function dmiInit() { return { prev: undefined, trur: 0, bp: 0, bm: 0, ba: 0 } }

    function volStep(s, bar) {                            // Waddah-style volume force / pressure
        const v = bar.volume
        const fast = s.n === 0 ? v : v * (2 / (P.volFast + 1)) + s.fast * (1 - 2 / (P.volFast + 1))
        const slow = s.n === 0 ? v : v / P.volSlow + (1 - 1 / P.volSlow) * s.slow
        const dir = bar.close > bar.open ? 1 : (bar.close < bar.open ? -1 : 0)
        const win = s.win.concat([[dir * v, v]]).slice(-P.volPressureLen)
        let signed = 0, total = 0
        for (const w of win) { signed += w[0]; total += w[1] }
        return {
            state: { n: s.n + 1, fast, slow, win },
            out: {
                force: slow > 0 ? fast / slow : 0,           // "explosion" over "dead zone"
                spike: s.slow > 0 ? v / s.slow : 0,          // this bar vs the baseline before it
                pressure: total > 0 ? signed / total : 0      // -1 all volume on down bars .. +1 up bars
            }
        }
    }
    function volInit() { return { n: 0, fast: 0, slow: 0, win: [] } }

    const STEPS = [['rsi', rsiStep, rsiInit], ['waddah', waddahStep, waddahInit], ['dmi', dmiStep, dmiInit], ['vol', volStep, volInit]]

    function stepAll(states, bar) {
        const next = {}, out = {}
        for (const [name, step] of STEPS) {
            const r = step(states[name], bar)
            next[name] = r.state
            out[name] = r.out
        }
        return { states: next, out }
    }
    function initAll() {
        const s = {}
        for (const [name, , init] of STEPS) { s[name] = init() }
        return s
    }

    /* ---------------------------------------------------------------- per time frame series
    For each base record i and time frame, perTF[key][i] = { closed, forming, bucketId }. */
    const perTF = {}
    for (const tf of TFS) {
        const period = Math.max(tf.ms, baseTF)
        const rows = new Array(candles.length)
        let states = initAll()
        let lastClosedOut
        let bucketId, bar
        const closedByBucket = new Map()
        for (let i = 0; i < candles.length; i++) {
            const c = candles[i]
            const id = Math.floor(c.begin / period)
            const vol = volumeByBegin.has(c.begin) ? volumeByBegin.get(c.begin) : 0
            if (bar !== undefined && id !== bucketId) {          // gap: a bucket ended without its last record
                const r = stepAll(states, bar)
                states = r.states; lastClosedOut = r.out; closedByBucket.set(bucketId, r.out)
                bar = undefined
            }
            if (bar === undefined) {
                bucketId = id
                bar = { open: c.open, close: c.close, max: c.max, min: c.min, volume: vol }
            } else {
                bar = { open: bar.open, close: c.close, max: Math.max(bar.max, c.max), min: Math.min(bar.min, c.min), volume: bar.volume + vol }
            }
            const bucketEnd = (id + 1) * period - 1
            let forming
            if (c.end >= bucketEnd) {                             // record completes the bucket
                const r = stepAll(states, bar)
                states = r.states; lastClosedOut = r.out; closedByBucket.set(id, r.out)
                forming = r.out
                bar = undefined
            } else {
                forming = stepAll(states, bar).out
            }
            rows[i] = { closed: lastClosedOut, forming, bucketId: id }
        }
        if (bar !== undefined) { closedByBucket.set(bucketId, stepAll(states, bar).out) }
        for (const r of rows) { r.lookahead = closedByBucket.get(r.bucketId) }
        perTF[tf.key] = rows
    }

    /* ---------------------------------------------------------------- classification */
    const ZERO = { rsi: { rsi: 0, k: 0 }, waddah: { up: 0, down: 0, pctB: 0.5, explosion: 0, deadZone: 0 }, dmi: { adx: 0 }, vol: { force: 0, spike: 0, pressure: 0 } }
    const COARSE = { BULL_STRONG: 'bull', BULL_WEAK: 'bull', BULL_PULLBACK: 'bull', BEAR_STRONG: 'bear', BEAR_WEAK: 'bear', BEAR_BOUNCE: 'bear', TRANSITIONING: 'sideways' }
    const sign = x => x > 0 ? 1 : (x < 0 ? -1 : 0)
    const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x))
    const r1 = x => Number.isFinite(x) ? Math.round(x * 10) / 10 : 0
    const r2 = x => Number.isFinite(x) ? Math.round(x * 100) / 100 : 0
    const r3 = x => Number.isFinite(x) ? Math.round(x * 1000) / 1000 : 0
    const days = ms => r2(ms / DAY)
    const stableBars = Math.max(1, Math.ceil(P.stableHours * HOUR / baseTF))

    function pick(key, i, volume) {
        const row = perTF[key][i]
        const o = volume === true ? row.closed : (P.htfMode === 'forming' ? row.forming : (P.htfMode === 'lookahead' ? row.lookahead : row.closed))
        return o === undefined ? ZERO : o
    }
    function heatOf(o) {
        const pb = clamp((o.waddah.pctB - 0.5) * 200, -100, 100)
        return clamp(0.4 * (o.rsi.rsi - 50) * 2 + 0.2 * (o.rsi.k - 50) * 2 + 0.4 * pb, -100, 100)
    }

    const out = new Array(candles.length)
    let coarseRun, fineRun, prevCoarse, prevFine, stable, pending
    for (let i = 0; i < candles.length; i++) {
        const c = candles[i]
        const o = {}
        for (const tf of TFS) { o[tf.key] = pick(tf.key, i) }
        const combined = {}
        for (const tf of TFS) {
            const x = o[tf.key]
            combined[tf.key] = sign(x.rsi.rsi - P.rsiBull) + sign(x.waddah.up - x.waddah.down)
        }
        const macro = combined['24h'] >= 1 ? 'BULL' : (combined['24h'] <= -1 ? 'BEAR' : 'MIXED')
        const localSum = combined['04h'] + combined['01h']
        const local = localSum >= 2 ? 'BULL' : (localSum <= -2 ? 'BEAR' : 'MIXED')
        const score = combined['24h'] * 2 + combined['12h'] + combined['04h'] + combined['01h']
        const sField = P.strengthSource === 'plusDI' ? 'plusDI' : 'adx'
        const strength = ((o['01h'].dmi[sField] || 0) + (o['04h'].dmi[sField] || 0) + (o['12h'].dmi[sField] || 0) + (o['24h'].dmi[sField] || 0)) / 4
        let regime = 'TRANSITIONING'
        if (macro === 'BULL') {
            regime = local === 'BEAR' ? 'BULL_PULLBACK' : ((local === 'BULL' && strength > P.adxTrending) ? 'BULL_STRONG' : 'BULL_WEAK')
        } else if (macro === 'BEAR') {
            regime = local === 'BULL' ? 'BEAR_BOUNCE' : ((local === 'BEAR' && strength > P.adxTrending) ? 'BEAR_STRONG' : 'BEAR_WEAK')
        }
        const coarse = COARSE[regime]

        /* ages */
        if (coarseRun === undefined || coarseRun.value !== coarse) {
            if (coarseRun !== undefined) { prevCoarse = { value: coarseRun.value, ms: c.begin - coarseRun.begin } }
            coarseRun = { value: coarse, begin: c.begin, index: i }
        }
        if (fineRun === undefined || fineRun.value !== regime) {
            if (fineRun !== undefined) { prevFine = { value: fineRun.value, ms: c.begin - fineRun.begin } }
            fineRun = { value: regime, begin: c.begin, index: i }
        }
        /* hysteresis: switch the stable regime once a new coarse value has held stableBars bars;
        the new stable run is back-dated to where that value started. */
        if (stable === undefined) {
            stable = { value: coarse, begin: c.begin }
        } else if (coarse === stable.value) {
            pending = undefined
        } else {
            if (pending === undefined || pending.value !== coarse) { pending = { value: coarse, begin: c.begin, bars: 0 } }
            pending.bars++
            if (pending.bars >= stableBars) { stable = { value: pending.value, begin: pending.begin }; pending = undefined }
        }

        /* heat */
        const h1 = heatOf(o['01h']), h4 = heatOf(o['04h']), h24 = heatOf(o['24h'])
        const heat = 0.2 * h1 + 0.3 * h4 + 0.5 * h24
        let heatState = 'NEUTRAL'
        if (heat >= P.heatStrong) { heatState = 'OVERHEATED' } else if (heat >= P.heatMild) { heatState = 'HOT' } else if (heat <= -P.heatStrong) { heatState = 'BOTTOMED' } else if (heat <= -P.heatMild) { heatState = 'COLD' }
        let agreement = 'MIXED'
        if (h1 >= P.heatHot && h4 >= P.heatHot && h24 >= P.heatHot) { agreement = 'ALL_HOT' } else if (h1 <= -P.heatHot && h4 <= -P.heatHot && h24 <= -P.heatHot) { agreement = 'ALL_COLD' }

        /* volume: always from CLOSED bars (a forming bar's volume is partial) */
        const v1 = pick('01h', i, true).vol, v4 = pick('04h', i, true).vol, v24 = pick('24h', i, true).vol
        const dirSign = coarse === 'bull' ? 1 : (coarse === 'bear' ? -1 : 0)
        const volConfirm = (dirSign !== 0 && sign(v4.pressure + v24.pressure) === dirSign && Math.max(v4.force, v24.force) >= 1) ? 1 : 0
        let volClimax = 0
        if (Math.max(v4.spike, v24.spike) >= P.climaxSpike) {
            if (heat >= P.climaxHeat) { volClimax = 1 } else if (heat <= -P.climaxHeat) { volClimax = -1 }
        }
        const volDry = (v4.force < P.dryForce && v24.force < P.dryForce) ? 1 : 0

        out[i] = {
            regime, macro_trend: macro, local_trend: local, trend_score: score, trend_strength: r2(strength),
            coarse,
            coarse_age_bars: i - coarseRun.index + 1, coarse_age_days: days(c.end + 1 - coarseRun.begin),
            regime_age_bars: i - fineRun.index + 1, regime_age_days: days(c.end + 1 - fineRun.begin),
            prev_coarse: prevCoarse ? prevCoarse.value : 'none', prev_coarse_days: prevCoarse ? days(prevCoarse.ms) : 0,
            prev_regime: prevFine ? prevFine.value : 'none', prev_regime_days: prevFine ? days(prevFine.ms) : 0,
            coarse_stable: stable.value, coarse_stable_age_days: days(c.end + 1 - stable.begin),
            heat_01h: r1(h1), heat_04h: r1(h4), heat_24h: r1(h24), heat_mtf: r1(heat),
            heat_state: heatState, heat_agreement: agreement,
            rsi_01h: r2(o['01h'].rsi.rsi), rsi_04h: r2(o['04h'].rsi.rsi), rsi_24h: r2(o['24h'].rsi.rsi),
            vol_force_01h: r3(v1.force), vol_force_04h: r3(v4.force), vol_force_24h: r3(v24.force),
            vol_pressure_04h: r3(v4.pressure), vol_pressure_24h: r3(v24.pressure),
            vol_spike_max: r2(Math.max(v4.spike, v24.spike)),
            vol_confirm: volConfirm, vol_climax: volClimax, vol_dry: volDry
        }
    }
    if (P.debug === true || P.debug === 'true') { Object.defineProperty(out, 'perTF', { value: perTF, enumerable: false }) }
    return out
})()
